-- Function: public.sp_remove_user_from_organization
-- Backup generated on 2026-11-11 09:05:57

CREATE OR REPLACE PROCEDURE public.sp_remove_user_from_organization(IN p_tenant_id uuid, IN p_organization_id uuid, IN p_user_id uuid)  LANGUAGE plpgsql AS $procedure$ BEGIN     -- Inactivate membership in this organization ONLY     UPDATE organization_memberships     SET status = 'Inactive', updated_at = NOW()     WHERE user_id = p_user_id       AND organization_id = p_organization_id       AND tenant_id = p_tenant_id;      -- Revoke branch assignments in this organization ONLY     UPDATE user_branch_assignments     SET revoked_at = NOW()     WHERE user_id = p_user_id       AND organization_id = p_organization_id       AND tenant_id = p_tenant_id;      -- Remove classroom assignments belonging to this organization     DELETE FROM classroom_teachers ct     USING classrooms c, branches b     WHERE ct.classroom_id = c.id       AND c.branch_id = b.id       AND b.organization_id = p_organization_id       AND ct.user_id = p_user_id       AND ct.tenant_id = p_tenant_id; END; $procedure$ ;
